//! Shared inline Markdown parser for Pathland.
//!
//! Parses a small inline subset into a
//! [`pathland_core::AttributedString`]:
//!
//! - `**bold**` / `__bold__` → `FONT_WEIGHT` 700
//! - `*italic*` / `_italic_` → `FONT_STYLE` Italic
//! - `` `code` `` → `FONT_DESIGN` Monospaced
//! - `~~strikethrough~~` → `STRIKETHROUGH` 1
//! - `[label](url)` → link run (label text is parsed recursively)
//! - `\` escapes the next character
//!
//! Intraword underscores stay literal (`snake_case_name`), matching CommonMark
//! emphasis rules.
//!
//! The parser is `no_std` + `alloc` and is shared by every DSL: the Rust DSL
//! calls [`parse`] directly; foreign hosts (Java/JNA) call the C ABI exported
//! by the `pathland-markdown-capi` cdylib. Block-level Markdown, images, and
//! reference links are out of scope for v1.

#![no_std]

extern crate alloc;

#[cfg(test)]
extern crate std;

use alloc::string::String;
use alloc::vec::Vec;
use pathland_core::{AttributedString, LinkRun, StyleRun};

/// Parse inline Markdown into an [`AttributedString`].
///
/// Returns `None` only if the produced ranges fail the model's validation
/// (which should not happen for well-formed UTF-8 input; the parser never
/// splits code points).
#[must_use]
pub fn parse(input: &str) -> Option<AttributedString> {
    let mut text = String::new();
    let mut runs = Vec::new();
    let mut links = Vec::new();
    parse_into(input, &mut text, &mut runs, &mut links);
    AttributedString::new(text, runs, links).ok()
}

fn parse_into(input: &str, text: &mut String, runs: &mut Vec<StyleRun>, links: &mut Vec<LinkRun>) {
    let bytes = input.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'\\' => {
                let next = next_char(input, i + 1);
                match next {
                    Some((ch, end)) => {
                        text.push(ch);
                        i = end;
                    }
                    None => {
                        text.push('\\');
                        i += 1;
                    }
                }
            }
            b'*' if bytes.get(i + 1) == Some(&b'*') => {
                if let Some(end) = find_delimiter(input, i + 2, "**") {
                    let start = text.len();
                    parse_into(&input[i + 2..end], text, runs, links);
                    runs.push(StyleRun::new(byte_len(start), byte_len(text.len())).bold());
                    i = end + 2;
                } else {
                    text.push('*');
                    i += 1;
                }
            }
            b'*' => {
                if let Some(end) = find_delimiter(input, i + 1, "*") {
                    let start = text.len();
                    parse_into(&input[i + 1..end], text, runs, links);
                    runs.push(StyleRun::new(byte_len(start), byte_len(text.len())).italic());
                    i = end + 1;
                } else {
                    text.push('*');
                    i += 1;
                }
            }
            b'_' if bytes.get(i + 1) == Some(&b'_') && underscore_can_open(input, i) => {
                if let Some(end) = find_delimiter(input, i + 2, "__") {
                    let start = text.len();
                    parse_into(&input[i + 2..end], text, runs, links);
                    runs.push(StyleRun::new(byte_len(start), byte_len(text.len())).bold());
                    i = end + 2;
                } else {
                    text.push('_');
                    i += 1;
                }
            }
            b'_' if underscore_can_open(input, i) => {
                if let Some(end) = find_delimiter(input, i + 1, "_") {
                    let start = text.len();
                    parse_into(&input[i + 1..end], text, runs, links);
                    runs.push(StyleRun::new(byte_len(start), byte_len(text.len())).italic());
                    i = end + 1;
                } else {
                    text.push('_');
                    i += 1;
                }
            }
            b'~' if bytes.get(i + 1) == Some(&b'~') => {
                if let Some(end) = find_delimiter(input, i + 2, "~~") {
                    let start = text.len();
                    parse_into(&input[i + 2..end], text, runs, links);
                    runs.push(StyleRun::new(byte_len(start), byte_len(text.len())).strikethrough());
                    i = end + 2;
                } else {
                    text.push('~');
                    i += 1;
                }
            }
            b'`' => {
                if let Some(end) = find_delimiter(input, i + 1, "`") {
                    let start = text.len();
                    text.push_str(&input[i + 1..end]);
                    runs.push(StyleRun::new(byte_len(start), byte_len(text.len())).monospaced());
                    i = end + 1;
                } else {
                    text.push('`');
                    i += 1;
                }
            }
            b'[' => {
                if let Some((label_end, url, after)) = parse_link(input, i) {
                    let start = text.len();
                    parse_into(&input[i + 1..label_end], text, runs, links);
                    links.push(LinkRun::new(byte_len(start), byte_len(text.len()), url));
                    i = after;
                } else {
                    text.push('[');
                    i += 1;
                }
            }
            _ => {
                let (ch, end) = next_char(input, i).expect("valid utf-8 boundary");
                text.push(ch);
                i = end;
            }
        }
    }
}

fn byte_len(value: usize) -> u32 {
    u32::try_from(value).unwrap_or(u32::MAX)
}

/// Underscore emphasis is not allowed intraword (`snake_case` stays literal).
fn underscore_can_open(input: &str, at: usize) -> bool {
    input[..at]
        .chars()
        .next_back()
        .is_none_or(|c| !c.is_alphanumeric())
}

fn underscore_can_close(input: &str, after_run: usize) -> bool {
    input[after_run..]
        .chars()
        .next()
        .is_none_or(|c| !c.is_alphanumeric())
}

/// Find the next closing delimiter at or after `from`, returning its byte
/// offset. Escaped characters are skipped.
///
/// Asterisk runs are split so nesting works: for a run of three (`***`) the
/// outer `**` close uses the last two stars and the inner `*` close uses the
/// first. A lone `*` never closes on a `**` run (that is nested bold).
fn find_delimiter(input: &str, from: usize, needle: &str) -> Option<usize> {
    let bytes = input.as_bytes();
    let mut i = from;
    while i < bytes.len() {
        if bytes[i] == b'\\' {
            i += 2;
            continue;
        }
        match needle {
            "**" => {
                if bytes[i] == b'*' {
                    let mut end = i;
                    while end < bytes.len() && bytes[end] == b'*' {
                        end += 1;
                    }
                    if end - i >= 2 {
                        return Some(end - 2);
                    }
                }
            }
            "*" => {
                if bytes[i] == b'*' {
                    let mut end = i;
                    while end < bytes.len() && bytes[end] == b'*' {
                        end += 1;
                    }
                    if end - i == 1 {
                        return Some(i);
                    }
                    i = end;
                    continue;
                }
            }
            "__" => {
                if bytes[i] == b'_' {
                    let mut end = i;
                    while end < bytes.len() && bytes[end] == b'_' {
                        end += 1;
                    }
                    if end - i >= 2 && underscore_can_close(input, end) {
                        return Some(end - 2);
                    }
                }
            }
            "_" => {
                if bytes[i] == b'_' {
                    let mut end = i;
                    while end < bytes.len() && bytes[end] == b'_' {
                        end += 1;
                    }
                    if end - i == 1 && underscore_can_close(input, end) {
                        return Some(i);
                    }
                    i = end;
                    continue;
                }
            }
            "~~" => {
                if bytes[i] == b'~' {
                    let mut end = i;
                    while end < bytes.len() && bytes[end] == b'~' {
                        end += 1;
                    }
                    if end - i >= 2 {
                        return Some(end - 2);
                    }
                }
            }
            _ => {
                if input[i..].starts_with(needle) {
                    return Some(i);
                }
            }
        }
        i = next_char(input, i)?.1;
    }
    None
}

/// Parse `[label](url)` at `open`. Returns `(label_end, url, after_close)`.
fn parse_link(input: &str, open: usize) -> Option<(usize, &str, usize)> {
    let bytes = input.as_bytes();
    let mut i = open + 1;
    while i < bytes.len() {
        if bytes[i] == b'\\' {
            i += 2;
            continue;
        }
        if bytes[i] == b']' && bytes.get(i + 1) == Some(&b'(') {
            let label_end = i;
            let url_start = i + 2;
            let mut j = url_start;
            while j < bytes.len() {
                if bytes[j] == b'\\' {
                    j += 2;
                    continue;
                }
                if bytes[j] == b')' {
                    return Some((label_end, &input[url_start..j], j + 1));
                }
                j = next_char(input, j)?.1;
            }
            return None;
        }
        i = next_char(input, i)?.1;
    }
    None
}

fn next_char(input: &str, at: usize) -> Option<(char, usize)> {
    let ch = input[at..].chars().next()?;
    Some((ch, at + ch.len_utf8()))
}

#[cfg(test)]
mod tests {
    use super::*;
    use pathland_core::{property_id, value_type};

    fn decoded(markdown: &str) -> AttributedString {
        parse(markdown).expect("parser output is valid")
    }

    #[test]
    fn plain_text_has_no_runs() {
        let value = decoded("hello");
        assert_eq!(value.text(), "hello");
        assert!(value.runs().is_empty());
        assert!(value.links().is_empty());
    }

    #[test]
    fn maps_each_inline_marker() {
        let value = decoded("**b** *i* `c` ~~s~~");
        assert_eq!(value.text(), "b i c s");
        assert_eq!(value.runs().len(), 4);
        assert_eq!(value.runs()[0].start, 0);
        assert_eq!(value.runs()[0].end, 1);
        assert!(value.runs()[0]
            .attributes
            .iter()
            .any(|a| { a.property == property_id::FONT_WEIGHT && a.value == 700.0f32.to_bits() }));
        assert!(value.runs()[1]
            .attributes
            .iter()
            .any(|a| { a.property == property_id::FONT_STYLE && a.value == 1.0f32.to_bits() }));
        assert!(value.runs()[2]
            .attributes
            .iter()
            .any(|a| { a.property == property_id::FONT_DESIGN && a.value == 3.0f32.to_bits() }));
        assert!(value.runs()[3].attributes.iter().any(|a| {
            a.property == property_id::STRIKETHROUGH && a.value_type == value_type::U8
        }));
    }

    #[test]
    fn nests_formats() {
        let value = decoded("**bold *and italic***");
        assert_eq!(value.text(), "bold and italic");
        assert_eq!(value.runs().len(), 2);
        assert_eq!(value.runs()[0].start, 5);
        assert_eq!(value.runs()[0].end, 15);
        assert_eq!(value.runs()[1].start, 0);
        assert_eq!(value.runs()[1].end, 15);
    }

    #[test]
    fn links_carry_label_runs_and_url() {
        let value = decoded("[**hi**](https://example.com)");
        assert_eq!(value.text(), "hi");
        assert_eq!(value.links().len(), 1);
        assert_eq!(value.links()[0].url, "https://example.com");
        assert_eq!(value.links()[0].start, 0);
        assert_eq!(value.links()[0].end, 2);
        assert_eq!(value.runs().len(), 1);
    }

    #[test]
    fn code_spans_do_not_parse_inner_markup() {
        let value = decoded("`**not bold**`");
        assert_eq!(value.text(), "**not bold**");
        assert_eq!(value.runs().len(), 1);
        assert_eq!(
            value.runs()[0].attributes[0].property,
            property_id::FONT_DESIGN
        );
    }

    #[test]
    fn underscore_emphasis_matches_asterisk_forms() {
        let value = decoded("_italic_ and __bold__");
        assert_eq!(value.text(), "italic and bold");
        assert_eq!(value.runs().len(), 2);
        assert!(value.runs()[0]
            .attributes
            .iter()
            .any(|a| a.property == property_id::FONT_STYLE));
        assert!(value.runs()[1]
            .attributes
            .iter()
            .any(|a| a.property == property_id::FONT_WEIGHT));
    }

    #[test]
    fn intraword_underscores_stay_literal() {
        let value = decoded("snake_case_name");
        assert_eq!(value.text(), "snake_case_name");
        assert!(value.runs().is_empty());
    }

    #[test]
    fn escaped_underscores_are_literal() {
        let value = decoded(r"\_not italic\_");
        assert_eq!(value.text(), "_not italic_");
        assert!(value.runs().is_empty());
    }

    #[test]
    fn escapes_are_literal() {
        let value = decoded(r"\*not italic\*");
        assert_eq!(value.text(), "*not italic*");
        assert!(value.runs().is_empty());
    }

    #[test]
    fn unmatched_markers_stay_literal() {
        let value = decoded("a * b ** c");
        assert_eq!(value.text(), "a * b ** c");
        assert!(value.runs().is_empty());
    }

    #[test]
    fn utf8_offsets_are_bytes() {
        let value = decoded("é**ü**");
        assert_eq!(value.text(), "éü");
        assert_eq!(value.runs()[0].start, 2);
        assert_eq!(value.runs()[0].end, 4);
    }
}

package dev.pathland.view.core

import dev.pathland.view.core.protocol.Properties
import dev.pathland.view.core.protocol.ValueTypes
import java.io.ByteArrayOutputStream
import java.nio.charset.StandardCharsets

/**
 * A scalar text-format attribute on a range.
 *
 * [value] is the standard 4-byte wire value (an `F32` bit pattern for float
 * attributes, a packed `0xAARRGGBB` for colors, `0`/`1` for booleans).
 */
data class TextAttribute(
    val property: Int,
    val valueType: Int = ValueTypes.forProperty(property),
    val value: Int,
) {
    companion object {
        @JvmStatic fun fontSize(points: Float) =
            TextAttribute(Properties.FONT_SIZE, ValueTypes.F32, points.toRawBits())

        @JvmStatic fun fontWeight(weight: Float) =
            TextAttribute(Properties.FONT_WEIGHT, ValueTypes.F32, weight.toRawBits())

        @JvmStatic fun color(argb: Int) =
            TextAttribute(Properties.COLOR, ValueTypes.COLOR, argb)

        @JvmStatic fun italic() =
            TextAttribute(Properties.FONT_STYLE, ValueTypes.F32, 1.0f.toRawBits())

        @JvmStatic fun fontDesign(code: Int) =
            TextAttribute(Properties.FONT_DESIGN, ValueTypes.F32, code.toFloat().toRawBits())

        @JvmStatic fun underline(on: Boolean = true) =
            TextAttribute(Properties.UNDERLINE, ValueTypes.U8, if (on) 1 else 0)

        @JvmStatic fun strikethrough(on: Boolean = true) =
            TextAttribute(Properties.STRIKETHROUGH, ValueTypes.U8, if (on) 1 else 0)
    }
}

/** A range of the text with a set of scalar attributes (UTF-8 byte offsets). */
data class StyleRun(
    val start: Int,
    val end: Int,
    val attributes: List<TextAttribute>,
) {
    fun bold() = copy(attributes = attributes + TextAttribute.fontWeight(700f))
    fun italic() = copy(attributes = attributes + TextAttribute.italic())
    fun monospaced() = copy(attributes = attributes + TextAttribute.fontDesign(3))
    fun strikethrough() = copy(attributes = attributes + TextAttribute.strikethrough())
    fun underline() = copy(attributes = attributes + TextAttribute.underline())

    companion object {
        @JvmStatic fun of(start: Int, end: Int) = StyleRun(start, end, emptyList())
    }
}

/** A range of the text that is a hyperlink (UTF-8 byte offsets). */
data class LinkRun(val start: Int, val end: Int, val url: String)

/**
 * Text plus range-scoped style runs and links — the app-side model for
 * `PARAMETER::SET_ATTRIBUTED_TEXT`.
 *
 * Ranges are **UTF-8 byte offsets** (the wire convention). The [Builder] takes
 * Kotlin character indices and converts them at [Builder.build]; markdown
 * payloads decode directly into byte offsets.
 */
class AttributedString private constructor(
    val text: String,
    val runs: List<StyleRun>,
    val links: List<LinkRun>,
) {
    init {
        val length = text.toByteArray(StandardCharsets.UTF_8).size
        for (run in runs) {
            require(run.start in 0..run.end && run.end <= length) {
                "style run ${run.start}..${run.end} is outside the text ($length bytes)"
            }
        }
        for (link in links) {
            require(link.start in 0..link.end && link.end <= length) {
                "link ${link.start}..${link.end} is outside the text ($length bytes)"
            }
        }
    }

    /** Whether this carries no style runs or links (plain text). */
    val isPlain: Boolean
        get() = runs.isEmpty() && links.isEmpty()

    override fun equals(other: Any?): Boolean =
        other is AttributedString &&
            text == other.text &&
            runs == other.runs &&
            links == other.links

    override fun hashCode(): Int {
        var result = text.hashCode()
        result = 31 * result + runs.hashCode()
        result = 31 * result + links.hashCode()
        return result
    }

    override fun toString(): String =
        "AttributedString(text=$text, runs=$runs, links=$links)"

    /** Encode the `SET_ATTRIBUTED_TEXT` payload (without the arena length wrapper). */
    fun encode(): ByteArray {
        val textBytes = text.toByteArray(StandardCharsets.UTF_8)
        val out = ByteArrayOutputStream()
        out.writeIntLE(textBytes.size)
        out.write(textBytes)
        out.writeIntLE(runs.size)
        for (run in runs) {
            out.writeIntLE(run.start)
            out.writeIntLE(run.end)
            val supported = run.attributes.filter { isSupported(it) }
            out.writeIntLE(supported.size)
            for (attr in supported) {
                out.writeShortLE(attr.property)
                out.write(attr.valueType and 0xFF)
                out.write(0)
                out.writeIntLE(attr.value)
            }
        }
        out.writeIntLE(links.size)
        for (link in links) {
            val url = link.url.toByteArray(StandardCharsets.UTF_8)
            out.writeIntLE(link.start)
            out.writeIntLE(link.end)
            out.writeIntLE(url.size)
            out.write(url)
        }
        return out.toByteArray()
    }

    companion object {
        private val SUPPORTED = setOf(
            Properties.FONT_SIZE,
            Properties.FONT_WEIGHT,
            Properties.COLOR,
            Properties.FONT_STYLE,
            Properties.FONT_DESIGN,
            Properties.UNDERLINE,
            Properties.STRIKETHROUGH,
        )

        private fun isSupported(attribute: TextAttribute): Boolean =
            attribute.property in SUPPORTED

        @JvmStatic fun plain(text: String) = AttributedString(text, emptyList(), emptyList())

        @JvmStatic
        fun of(text: String, runs: List<StyleRun>, links: List<LinkRun>) =
            AttributedString(text, runs, links)

        /** Start a range-tracking builder (inputs are Kotlin character indices). */
        @JvmStatic fun builder(): Builder = Builder()

        /** Decode a native markdown payload (UTF-8 byte offsets already). */
        @JvmStatic
        fun decode(payload: ByteArray): AttributedString {
            var p = 0
            fun need(n: Int) {
                require(p + n <= payload.size) { "attributed text payload truncated" }
            }
            fun i32(): Int {
                need(4)
                val value = (payload[p].toInt() and 0xFF) or
                    ((payload[p + 1].toInt() and 0xFF) shl 8) or
                    ((payload[p + 2].toInt() and 0xFF) shl 16) or
                    ((payload[p + 3].toInt() and 0xFF) shl 24)
                p += 4
                return value
            }
            fun i16(): Int {
                need(2)
                val value = (payload[p].toInt() and 0xFF) or
                    ((payload[p + 1].toInt() and 0xFF) shl 8)
                p += 2
                return value
            }
            fun bytes(n: Int): ByteArray {
                need(n)
                val value = payload.copyOfRange(p, p + n)
                p += n
                return value
            }

            val textLen = i32()
            val text = String(bytes(textLen), StandardCharsets.UTF_8)
            val runCount = i32()
            val runs = ArrayList<StyleRun>(runCount)
            repeat(runCount) {
                val start = i32()
                val end = i32()
                val attrCount = i32()
                val attributes = ArrayList<TextAttribute>(attrCount)
                repeat(attrCount) {
                    val property = i16()
                    val valueType = payload[p++].toInt() and 0xFF
                    p++ // reserved
                    val value = i32()
                    val attribute = TextAttribute(property, valueType, value)
                    if (isSupported(attribute)) {
                        attributes.add(attribute)
                    }
                }
                runs.add(StyleRun(start, end, attributes))
            }
            val linkCount = i32()
            val links = ArrayList<LinkRun>(linkCount)
            repeat(linkCount) {
                val start = i32()
                val end = i32()
                val urlLen = i32()
                val url = String(bytes(urlLen), StandardCharsets.UTF_8)
                links.add(LinkRun(start, end, url))
            }
            return AttributedString(text, runs, links)
        }
    }

    /** Range-tracking builder: append text, then mark character ranges. */
    class Builder internal constructor() {
        private val text = StringBuilder()
        private val runs = ArrayList<StyleRun>()
        private val links = ArrayList<LinkRun>()

        fun append(value: String): Builder {
            text.append(value)
            return this
        }

        fun bold(start: Int, end: Int): Builder = style(start, end, TextAttribute.fontWeight(700f))
        fun italic(start: Int, end: Int): Builder = style(start, end, TextAttribute.italic())
        fun monospaced(start: Int, end: Int): Builder = style(start, end, TextAttribute.fontDesign(3))
        fun underline(start: Int, end: Int): Builder = style(start, end, TextAttribute.underline())
        fun strikethrough(start: Int, end: Int): Builder =
            style(start, end, TextAttribute.strikethrough())

        fun fontSize(start: Int, end: Int, points: Float): Builder =
            style(start, end, TextAttribute.fontSize(points))

        fun color(start: Int, end: Int, argb: Int): Builder =
            style(start, end, TextAttribute.color(argb))

        fun link(start: Int, end: Int, url: String): Builder {
            links.add(LinkRun(byteOffset(start), byteOffset(end), url))
            return this
        }

        private fun style(start: Int, end: Int, attribute: TextAttribute): Builder {
            runs.add(
                StyleRun(byteOffset(start), byteOffset(end), listOf(attribute)),
            )
            return this
        }

        private fun byteOffset(charIndex: Int): Int {
            val value = text.toString()
            require(charIndex in 0..value.length) { "character index $charIndex is out of range" }
            return value.substring(0, charIndex).toByteArray(StandardCharsets.UTF_8).size
        }

        fun build(): AttributedString =
            AttributedString(text.toString(), runs.toList(), links.toList())
    }
}

private fun ByteArrayOutputStream.writeIntLE(value: Int) {
    write(value and 0xFF)
    write((value ushr 8) and 0xFF)
    write((value ushr 16) and 0xFF)
    write((value ushr 24) and 0xFF)
}

private fun ByteArrayOutputStream.writeShortLE(value: Int) {
    write(value and 0xFF)
    write((value ushr 8) and 0xFF)
}
